Component(
  dsl: 1, id: "market/cart-icon-badge", name: "Cart icon with count", kind: Kind.section,
  description: "A cart button showing how many items are in it.",
  variants: [Variant(id: "default", label: "Default", build:
    Stack(width: 48, height: 48, children: [
      Positioned(top: 4, left: 4, child: Box(shape: BoxShape.circle, width: 40, height: 40, alignment: Anchor.center, background: Color.surface, border: Border(width: 1), onTap: Navigate(to: Route.cart), ariaLabel: "Cart", child: Icon(name: Icons.cart))),
      Positioned(top: 0, right: 0, child: If(condition: cart.count > 0, then: Box(shape: BoxShape.circle, width: 20, height: 20, alignment: Anchor.center, background: Color.primary, child: Text(child: cart.count, size: FontSize.xs, weight: FontWeight.bold, color: Color.primaryInk))))
    ])
  )], data: [Data(name: "cart", from: Client.cart(), fetch: "client", type: Cart)],
)
